// PRUNE FLOOR — per kind, durable, resolvable
for k, n := range stored {
    if n == 0 || ratio <= 0 || float64(thisRun[k]) >= ratio*float64(n) { safe = append(safe, k); continue }
    refused = append(refused, map[string]interface{}{"kind": k, "this_run": thisRun[k], "stored": n})
}
if len(refused) > 0 { recordIndexNote(ctx, params.DB, "prune refused", "", refused) }

// REAL CODE, not a comment. doc_notes: site_id NULLABLE, append-only, and the
// trail this subsystem already keeps (migration 244). NOT site_work_items —
// its site_id/handler_agent/pipeline are NOT NULL and this indexer is repo-wide.
func recordIndexNote(ctx context.Context, db *sql.DB, what, detail string, payload interface{}) {
    b, _ := json.Marshal(payload)
    _, err := db.ExecContext(ctx, `INSERT INTO doc_notes
        (subject_type, subject_key, body, categories, source, created_by)
        VALUES ('action','index_code_symbols',$1,$2::jsonb,'index_code_symbols run','code-indexer')`,
        fmt.Sprintf("%s: %s %s — remedy: re-run with prune_floor_ratio=0 to accept a "+
            "legitimate large deletion.", what, detail, string(b)),
        `["code-index","index-prune-refused","landmine"]`)
    if err != nil { logger.Error("could not record index note", zap.Error(err)) }
}
return map[string]interface{}{..., "prune_refused": refused, "doc_sections": len(docRows),
